type ClaudeRuntime = {
  kind: "claude";
  sdkSessionId: string | null;
  forkFromSdkSessionId: string | null;
  query: ClaudeQuery | null;
  inputPump: ClaudeInputPump | null;
  /** In-flight query start. Concurrent ensureClaudeQuery callers latch onto
   * one start — two racing starts used to spawn twin subprocesses resuming
   * the same SDK session. */
  queryStartPromise: Promise<ClaudeQuery> | null;
  pendingPostResultNext: Promise<IteratorResult<SDKMessage, void>> | null;
  pendingPostResultNextSettledAt: number | null;
  idleReaderPromise: Promise<void> | null;
  idleReaderGeneration: number;
  queryGeneration: number;
  warmQuery: WarmQuery | null;
  /** Resolves when startup() has produced a warm query handle. */
  warmupDone: Promise<void> | null;
  /** Resolves the current warmup race so waiters can stop blocking immediately. */
  warmupCancel: (() => void) | null;
  /** Set to true when teardown runs to cancel an in-flight warmup. */
  warmupCancelled: boolean;
  activeSubagents: Map<string, ClaudeActiveSubagent>;
  emittedSubagentStartIds: Set<string>;
  /**
   * Stash for Task-tool inputs captured at the assistant tool_use boundary,
   * keyed by the Task tool_use_id. Lets the `system:task_*` system-message
   * path enrich its envelopes with the `subagent_type` the model picked
   * (e.g. "code-reviewer", "Explore") instead of falling back to "subagent".
   */
  taskToolInputByToolUseId: Map<string, {
    subagentType?: string;
    name?: string;
    description?: string;
    isBackground?: boolean;
  }>;
  /**
   * Per-workflow-task emit state for the SDK's undocumented
   * `workflow_progress` snapshot on system:task_progress. Keyed by the
   * workflow taskId → per-agent transition tracking, so cumulative snapshots
   * fan out as started/progress/result events under stable identities
   * instead of duplicating rows (see claudeWorkflowProgress.ts).
   */
  workflowAgentsByTask: Map<string, Map<string, ClaudeWorkflowAgentEmitState>>;
  scheduledWorkSignatures: Map<string, string>;
  /**
   * Claude Code TaskCreate/TaskUpdate tracker. The harness assigns ordinal
   * task ids ("1", "2", …) in the TaskCreate tool *result*, which this
   * input-side tracker never sees, so creates are keyed by their tool_use id
   * and remapped onto the ordinal id the first time an update or runtime
   * event references it. Insertion order mirrors creation order — the
   * ordinal remap depends on it. Lazily seeded from the transcript's latest
   * todo_update so cross-turn updates keep resolving.
   */
  taskTodos: { seeded: boolean; byId: Map<string, ClaudeTaskTodoState> };
  /**
   * Cumulative assistant text already emitted per SDK message id + content
   * index, shared across foreground and idle turns. The SDK re-delivers full
   * assistant snapshots after the per-stream dedup state was reset (message
   * interleave, steer, idle handoff), which used to double the transcript —
   * this durable record is the guard. Bounded to the most recent messages.
   */
  emittedTextByAssistantMessage: Map<string, Map<number, string>>;
  /**
   * Full level-set reported by SDK `background_tasks_changed`. Unlike paired
   * task edge events, this cannot leave ADE believing a finished task is live
   * (or miss a still-live task after an edge race). It exists primarily to
   * protect the long-lived query from idle cleanup and runtime eviction.
   */
  liveBackgroundTaskIds: Set<string>;
  /** True after this CLI process has emitted its first authoritative level. */
  backgroundTasksLevelObserved: boolean;
  seenBackgroundTaskIds: Set<string>;
  /**
   * Sticky per-background-task title, keyed by taskId. The first meaningful
   * title (the spawn description) is recorded here and reused for every later
   * update — including the terminal stopped/completed row — so a background
   * task never loses its name to a generic "Background work" fallback or a
   * stale progress string once it has been named.
   */
  backgroundTaskTitleById: Map<string, string>;
  scheduledWorkKindById: Map<string, AgentChatScheduledWorkKind>;
  scheduledWorkIdByTaskId: Map<string, string>;
  scheduledWorkIdByToolUseId: Map<string, string>;
  activeProviderCronIds: Set<string>;
  activeProviderCronIdsByPrompt: Map<string, Set<string>>;
  slashCommands: Array<{ name: string; description: string; argumentHint?: string }>;
  busy: boolean;
  activeTurnId: string | null;
  /** Orders active-turn steers after the parent turn's first SDK input push. */
  initialInputDispatchGate: {
    turnId: string;
    promise: Promise<void>;
    resolve: () => void;
    reject: (error: Error) => void;
    settled: boolean;
  } | null;
  /** Prevents turn-finalization from auto-delivering a staged row while the
   * user is explicitly dispatching it with Claude's priority queue. */
  dispatchingSteerIds: Set<string>;
  pendingSteers: QueuedSteer[];
  knownQueuedMessages: Map<string, { preview: string; steerId?: string }>;
  commandLifecycleByUuid: Map<string, "queued" | "started" | "completed" | "cancelled" | "discarded">;
  contextGuardrail: ClaudeContextGuardrailState;
  approvals: Map<string, PendingClaudeApproval>;
  interrupted: boolean;
  /** Set when early interrupt events have been emitted to avoid duplicate emission later. */
  interruptEventsEmitted: boolean;
  /** Set when a reasoning effort change is requested mid-turn; flushed when idle. */
  pendingSessionReset?: boolean;
  /** Clear Claude SDK continuity on the deferred reset; used after mode changes the old session cannot apply. */
  pendingSessionResetClearSdkSessionId?: boolean;
  /** Tool names the user has approved for the session via "Allow for Session". */
  approvalOverrides: Set<string>;
  /** SDK tool_use IDs resolved by canUseTool (e.g. answered AskUserQuestion). */
  resolvedToolUseIds: Set<string>;
  /** Suspend the active-turn idle watchdog while ADE is waiting on human input. */
  pauseIdleWatchdog?: (() => void) | null;
  /** Resume the active-turn idle watchdog after the blocking wait finishes. */
  resumeIdleWatchdog?: (() => void) | null;
  /** Set after we've emitted the once-per-session "Approaching plan limit" notice. */
  rateLimitWarningEmitted: boolean;
};

function resetClaudeProcessBackgroundLevel(runtime: ClaudeRuntime): void {
  runtime.liveBackgroundTaskIds.clear();
  runtime.backgroundTasksLevelObserved = false;
}

function settleClaudeInitialInputDispatch(
  runtime: ClaudeRuntime,
  error?: Error,
): void {
  const gate = runtime.initialInputDispatchGate;
  if (!gate || gate.settled) return;
  gate.settled = true;
  if (runtime.initialInputDispatchGate === gate) {
    runtime.initialInputDispatchGate = null;
  }
  if (error) gate.reject(error);
  else gate.resolve();
}

