function cancelCursorPermissionWaiter(waiter: CursorPermissionWaiter, reason: string): void {
  waiter.resolve(denyCursorHook(reason));
}

type DroidPermissionWaiter = {
  toolName: string;
  request: DroidSdkPermissionRequest;
  resolve: (value: DroidSdkPermissionDecision) => void;
};

function cancelDroidPermissionWaiter(waiter: DroidPermissionWaiter, reason: string): void {
  waiter.resolve({ selectedOption: "cancel", comment: reason });
}

function asRecord(value: unknown): Record<string, unknown> | null {
  return value && typeof value === "object" && !Array.isArray(value)
    ? value as Record<string, unknown>
    : null;
}

/**
 * `Cursor SDK Run.conversation()` returns a list of message-shaped records.
 * The shape can vary across SDK versions, so we walk it tolerantly: any
 * record that already looks like an SDK message gets fed back through
 * `mapCursorSdkMessageToChatEvents`; anything that just exposes
 * `{ role, text }` becomes a user/assistant text event directly.
 */
function flattenCloudConversationMessages(conversation: unknown): unknown[] {
  if (!conversation) return [];
  if (Array.isArray(conversation)) return conversation;
  const record = asRecord(conversation);
  if (!record) return [];
  if (Array.isArray(record.messages)) return record.messages;
  if (Array.isArray(record.content)) return record.content;
  if (Array.isArray(record.items)) return record.items;
  return [];
}

function isCloudRunStillLive(status: string | null | undefined): boolean {
  if (!status) return false;
  const lower = status.toLowerCase();
  return lower === "creating" || lower === "running" || lower === "queued";
}

function pickCodexTurnId(...values: unknown[]): string | undefined {
  for (const value of values) {
    if (typeof value !== "string") continue;
    const trimmed = value.trim();
    if (trimmed.length > 0) return trimmed;
  }
  return undefined;
}

function extractCodexTurnId(value: unknown): string | undefined {
  const record = asRecord(value);
  if (!record) return undefined;
  const nestedTurn = asRecord(record.turn);
  return pickCodexTurnId(record.turnId, record.turn_id, nestedTurn?.id);
}

function extractCodexThreadId(value: unknown): string | undefined {
  const record = asRecord(value);
  if (!record) return undefined;
  const nestedThread = asRecord(record.thread);
  return pickCodexTurnId(record.threadId, record.thread_id, nestedThread?.id);
}

function readCodexNotificationItemId(params: Record<string, unknown>): string | null {
  const nestedItem = asRecord(params.item);
  return pickCodexTurnId(params.itemId, nestedItem?.id) ?? null;
}

function codexNotificationDedupKey(payload: JsonRpcEnvelope): string | null {
  const method = typeof payload.method === "string" ? payload.method : "";
  const params = asRecord(payload.params) ?? {};

  switch (method) {
    case "item/started":
    case "codex/event/item_started": {
      const itemId = readCodexNotificationItemId(params);
      return itemId ? `item_started:${itemId}` : null;
    }
    case "item/completed":
    case "codex/event/item_completed": {
      const itemId = readCodexNotificationItemId(params);
      return itemId ? `item_completed:${itemId}` : null;
    }
    case "turn/aborted":
    case "codex/event/turn_aborted": {
      const turnId = extractCodexTurnId(params);
      return turnId ? `turn_aborted:${turnId}` : null;
    }
    default:
      return null;
  }
}

function shouldSkipDuplicateCodexNotification(runtime: CodexRuntime, payload: JsonRpcEnvelope): boolean {
  const key = codexNotificationDedupKey(payload);
  if (!key) return false;
  if (runtime.recentNotificationKeys.has(key)) return true;
  runtime.recentNotificationKeys.add(key);
  if (runtime.recentNotificationKeys.size > 2048) {
    runtime.recentNotificationKeys.clear();
    runtime.recentNotificationKeys.add(key);
  }
  return false;
}

function discardBufferedAssistantText(managed: ManagedChatSession): void {
  const buffered = managed.bufferedText;
  if (!buffered) return;
  if (buffered.timer) {
    clearTimeout(buffered.timer);
  }
  managed.bufferedText = null;
  managed.activeAssistantMessageId = null;
}

function resetAssistantMessageStream(managed: ManagedChatSession): void {
  managed.activeAssistantMessageId = null;
}

function ensureAssistantMessageId(
  managed: ManagedChatSession,
  event: Extract<AgentChatEvent, { type: "text" }>,
): Extract<AgentChatEvent, { type: "text" }> {
  const explicitMessageId = event.messageId?.trim() || null;
  if (explicitMessageId) {
    managed.activeAssistantMessageId = explicitMessageId;
    return explicitMessageId === event.messageId ? event : { ...event, messageId: explicitMessageId };
  }

  const activeMessageId = managed.activeAssistantMessageId ?? randomUUID();
  managed.activeAssistantMessageId = activeMessageId;
  return { ...event, messageId: activeMessageId };
}

function ensureLogicalItemId<T extends { itemId: string; logicalItemId?: string }>(event: T): T {
  const explicitLogicalItemId = event.logicalItemId?.trim() || null;
  if (explicitLogicalItemId) {
    return explicitLogicalItemId === event.logicalItemId ? event : { ...event, logicalItemId: explicitLogicalItemId };
  }

  const fallbackLogicalItemId = event.itemId.trim();
  if (!fallbackLogicalItemId.length) return event;
  return { ...event, logicalItemId: fallbackLogicalItemId };
}

function isCurrentCodexLifecycleTurn(
  runtime: CodexRuntime,
  turnId: string | null | undefined,
): boolean {
  const activeTurnId = runtime.activeTurnId ?? runtime.startedTurnId;
  if (runtime.awaitingTurnStart && turnId) {
    return activeTurnId ? activeTurnId === turnId : false;
  }
  if (!activeTurnId || !turnId) return true;
  return activeTurnId === turnId;
}

type CodexActiveTurnMismatch = {
  expectedTurnId: string;
  foundTurnId: string;
};

function trimCodexTurnIdToken(value: string): string {
  return value.trim().replace(/[.,;:)]+$/g, "");
}

function parseCodexActiveTurnMismatch(error: unknown): CodexActiveTurnMismatch | null {
  const record = asRecord(error);
  const message = error instanceof Error
    ? error.message
    : typeof error === "string"
      ? error
      : typeof record?.message === "string"
        ? record.message
        : String(error ?? "");
  const match = /expected active turn id\s+(\S+)\s+but found\s+(\S+)/i.exec(message);
  if (!match) return null;
  const expectedTurnId = trimCodexTurnIdToken(match[1] ?? "");
  const foundTurnId = trimCodexTurnIdToken(match[2] ?? "");
  if (!expectedTurnId || !foundTurnId) return null;
  if (/^(?:none|null|undefined)$/i.test(foundTurnId)) return null;
  return { expectedTurnId, foundTurnId };
}

function adoptCodexActiveTurnId(
  managed: ManagedChatSession,
  runtime: CodexRuntime,
  logger: Logger | null | undefined,
  foundTurnId: string,
  context: string,
  options: { markStarted?: boolean } = {},
): void {
  const previousTurnId = runtime.activeTurnId ?? runtime.startedTurnId ?? null;
  if (previousTurnId === foundTurnId) return;
  logger?.warn("agent_chat.codex_adopting_active_turn_id", {
    sessionId: managed.session.id,
    context,
    previousTurnId,
    foundTurnId,
  });
  runtime.awaitingTurnStart = false;
  runtime.canAttachResumedTurnStart = false;
  runtime.activeTurnId = foundTurnId;
  if (options.markStarted !== false) {
    runtime.startedTurnId = foundTurnId;
  }
}

function isCodexInProgressTurnStatus(value: unknown): boolean {
  return value === "inProgress" || value === "in_progress";
}

function rememberInterruptedCodexTurn(runtime: CodexRuntime, turnId: string | null | undefined): void {
  const normalizedTurnId = turnId?.trim() || null;
  if (!normalizedTurnId) return;
  runtime.interruptedTurnIds.add(normalizedTurnId);
  if (runtime.interruptedTurnIds.size > 64) {
    const [first] = runtime.interruptedTurnIds;
    if (first) runtime.interruptedTurnIds.delete(first);
  }
}

function isInterruptedCodexTurn(runtime: CodexRuntime, turnId: string | null | undefined): boolean {
  const normalizedTurnId = turnId?.trim() || null;
  return normalizedTurnId ? runtime.interruptedTurnIds.has(normalizedTurnId) : false;
}

function rememberBoundedId(set: Set<string>, value: string | null | undefined, limit = 64): void {
  const normalized = value?.trim() || null;
  if (!normalized) return;
  set.add(normalized);
  while (set.size > limit) {
    const [first] = set;
    if (!first) break;
    set.delete(first);
  }
}

function rememberTerminalCodexTurn(
  runtime: CodexRuntime,
  turnId: string | null | undefined,
  managed?: ManagedChatSession,
): void {
  const normalizedTurnId = turnId?.trim() || null;
  if (!normalizedTurnId) return;
  rememberBoundedId(runtime.terminalTurnIds, normalizedTurnId);
  runtime.planningApprovalGuardByTurnId.delete(normalizedTurnId);
  if (managed) rememberBoundedId(managed.codexTerminalTurnIds, normalizedTurnId);
}

function isTerminalCodexTurn(
  runtime: CodexRuntime,
  turnId: string | null | undefined,
  managed?: ManagedChatSession,
): boolean {
  const normalizedTurnId = turnId?.trim() || null;
  return normalizedTurnId
    ? runtime.terminalTurnIds.has(normalizedTurnId) || managed?.codexTerminalTurnIds.has(normalizedTurnId) === true
    : false;
}

function normalizeCodexAssistantDelta(
  runtime: CodexRuntime,
  args: {
    turnId?: string;
    itemId?: string;
    delta: string;
  },
): string | null {
  const turnId = args.turnId?.trim() || null;
  if (!turnId || args.itemId) {
    return args.delta;
  }

  const knownText = runtime.agentMessageTextByTurn.get(turnId) ?? "";
  if (!knownText.length) {
    runtime.agentMessageTextByTurn.set(turnId, args.delta);
    evictOldestEntries(runtime.agentMessageTextByTurn, MAX_SESSION_MAP_ENTRIES);
    return args.delta;
  }

  if (args.delta.startsWith(knownText)) {
    const suffix = args.delta.slice(knownText.length);
    runtime.agentMessageTextByTurn.set(turnId, args.delta);
    evictOldestEntries(runtime.agentMessageTextByTurn, MAX_SESSION_MAP_ENTRIES);
    return suffix.length ? suffix : null;
  }

  const nextText = `${knownText}${args.delta}`;
  runtime.agentMessageTextByTurn.set(turnId, nextText);
  evictOldestEntries(runtime.agentMessageTextByTurn, MAX_SESSION_MAP_ENTRIES);
  return args.delta;
}

const PENDING_INPUT_SEND_BLOCKED_MESSAGE = "Answer or decline the pending request before sending another message.";

function validateSessionReadyForTurn(managed: ManagedChatSession): { ready: true } | { ready: false; reason: string } {
  if (managed.closed) return { ready: false, reason: "Session is disposed" };
  if (!managed.runtime) return { ready: false, reason: "No runtime initialized" };
  if (hasLivePendingInput(managed)) return { ready: false, reason: PENDING_INPUT_SEND_BLOCKED_MESSAGE };
  const rt = managed.runtime;
  if ((rt.kind === "opencode" || rt.kind === "claude" || rt.kind === "cursor" || rt.kind === "droid") && rt.busy) {
    return { ready: false, reason: "Turn already active" };
  }
  if (rt.kind === "opencode" && rt.pendingApprovals.size > 0) return { ready: false, reason: "Pending approvals not resolved" };
  if ((rt.kind === "cursor" || rt.kind === "droid") && rt.permissionWaiters.size > 0) {
    return { ready: false, reason: "Pending permissions not resolved" };
  }
  return { ready: true };
}

function hasLivePendingInput(managed: ManagedChatSession | null | undefined): boolean {
  if (!managed) return false;
  if (managed.localPendingInputs.size > 0) return true;
  const runtime = managed.runtime;
  if (!runtime) return false;
  if (runtime.kind === "codex") return runtime.approvals.size > 0;
  if (runtime.kind === "claude") return runtime.approvals.size > 0;
  if (runtime.kind === "opencode") return runtime.pendingApprovals.size > 0;
  if (runtime.kind === "cursor" || runtime.kind === "droid") return runtime.permissionWaiters.size > 0;
  return false;
}

function hasRuntimeActiveWorkload(runtime: ChatRuntime | null): boolean {
  if (!runtime) return false;
  switch (runtime.kind) {
    case "codex":
      return Boolean(
        runtime.activeTurnId
        || runtime.startedTurnId
        || runtime.awaitingTurnStart
        || runtime.manualCompactionPending
        || runtime.pending.size > 0
        || runtime.approvals.size > 0
        || runtime.activeSubagents.size > 0
        || runtime.pendingPlanFollowups.length > 0
      );
    case "claude": {
      // Before the first level signal, task edge state is the only evidence we
      // have. Once observed, background_tasks_changed is authoritative for
      // background agents/shells; only foreground subagent edges remain an
      // independent workload signal.
      const hasUnlevelledSubagent = [...runtime.activeSubagents.values()].some(
        (subagent) => !subagent.background || !runtime.backgroundTasksLevelObserved,
      );
      return Boolean(
        runtime.busy
        || runtime.activeTurnId
        || runtime.pendingSteers.length > 0
        || runtime.approvals.size > 0
        || hasUnlevelledSubagent
        || runtime.liveBackgroundTaskIds.size > 0
      );
    }
    case "opencode":
      return Boolean(
        runtime.busy
        || runtime.activeTurnId
        || runtime.eventAbortController
        || runtime.pendingApprovals.size > 0
        || runtime.pendingSteers.length > 0
      );
    case "cursor":
      return Boolean(
        runtime.busy
        || runtime.activeTurnId
        || runtime.activeCloudRunId
        || runtime.cloudRuns.size > 0
        || runtime.pendingSteers.length > 0
        || runtime.permissionWaiters.size > 0
      );
    case "droid":
      return Boolean(
        runtime.busy
        || runtime.activeTurnId
        || runtime.pendingSteers.length > 0
        || runtime.permissionWaiters.size > 0
      );
    default:
      return false;
  }
}

function isSignalPermissionError(error: unknown): boolean {
  return Boolean(error && typeof error === "object" && "code" in error && (error as { code?: string }).code === "EPERM");
}

function isAbortRelatedError(error: unknown): boolean {
  if (typeof globalThis.DOMException === "function" && error instanceof globalThis.DOMException && error.name === "AbortError") return true;
  if (error instanceof Error && error.name === "AbortError") return true;
  const message = (error instanceof Error ? error.message : String(error)).toLowerCase();
  return message.includes("aborterror") || message.includes("aborted by user");
}

function isProcessAlive(pid: number | null): boolean {
  if (pid == null || !Number.isInteger(pid) || pid <= 0) return false;
  try {
    process.kill(pid, 0);
    return true;
  } catch (error) {
    return isSignalPermissionError(error);
  }
}

function isProcessGroupAlive(pid: number | null): boolean {
  if (process.platform === "win32") return false;
  if (pid == null || !Number.isInteger(pid) || pid <= 0) return false;
  try {
    process.kill(-pid, 0);
    return true;
  } catch (error) {
    return isSignalPermissionError(error);
  }
}

function signalChildProcessTree(
  child: ChildProcessWithoutNullStreams,
  signal: NodeJS.Signals,
): boolean {
  if (process.platform === "win32") {
    return terminateProcessTree(child, signal);
  }

  const pid = child.pid ?? null;
  if (pid != null && Number.isInteger(pid) && pid > 0) {
    try {
      process.kill(-pid, signal);
      return true;
    } catch {
      // Fall through to direct child signaling if the process group is gone.
    }
  }

  try {
    child.kill(signal);
    return true;
  } catch {
    // Fall through to direct PID signaling if the child wrapper rejects the signal.
  }

  if (pid == null || !Number.isInteger(pid) || pid <= 0) return false;
  try {
    process.kill(pid, signal);
    return true;
  } catch {
    return false;
  }
}

function terminateChildProcessTree(
  child: ChildProcessWithoutNullStreams,
  previousKillTimer: NodeJS.Timeout | null,
  killAfterMs = 1500,
): NodeJS.Timeout | null {
  if (previousKillTimer) {
    clearTimeout(previousKillTimer);
  }

  try {
    child.stdin.end();
  } catch {
    // ignore
  }

  const pid = child.pid ?? null;
  const signaled = signalChildProcessTree(child, "SIGTERM");
  if (!signaled || pid == null || !Number.isInteger(pid) || pid <= 0 || killAfterMs <= 0) {
    return null;
  }

  const timer = setTimeout(() => {
    if (process.platform === "win32") {
      if (!isProcessAlive(pid)) return;
      signalChildProcessTree(child, "SIGKILL");
      return;
    }
    if (!isProcessGroupAlive(pid)) return;
    signalChildProcessTree(child, "SIGKILL");
  }, killAfterMs);
  timer.unref?.();
  return timer;
}

function trimLine(value: string | null | undefined): string | null {
  const trimmed = typeof value === "string" ? value.trim() : "";
  return trimmed.length ? trimmed : null;
}

function normalizeHandoffNote(value: string | null | undefined): string | null {
  const note = trimLine(value);
  if (!note) return null;
  if (note.length > HANDOFF_NOTE_MAX_CHARS) {
    throw new Error(HANDOFF_NOTE_TOO_LONG_MESSAGE);
  }
  return note;
}

function uniqueNonEmpty(values: Array<string | null | undefined>, limit = values.length): string[] {
  const seen = new Set<string>();
  const result: string[] = [];
  for (const value of values) {
    const normalized = trimLine(value);
    if (!normalized || seen.has(normalized)) continue;
    seen.add(normalized);
    result.push(normalized);
    if (result.length >= limit) break;
  }
  return result;
}

type ClaudeBackgroundJobState = {
  state?: string;
  detail?: string;
  tempo?: string;
  output?: unknown;
  intent?: string;
  sessionId?: string;
  resumeSessionId?: string;
  daemonShort?: string;
  cwd?: string;
  updatedAt?: string;
  linkScanPath?: string;
};

type ClaudeDaemonRequest = {
  proto?: number;
  op: string;
  short?: string;
  text?: string;
};

type ClaudeDaemonResponse = {
  ok?: boolean;
  op?: string;
  jobs?: Array<Record<string, unknown>>;
  error?: string;
  code?: string;
  short?: string;
  alive?: boolean;
  present?: boolean;
};

const MAX_CLAUDE_DAEMON_RESPONSE_BYTES = 1024 * 1024;

function sleepMs(ms: number): Promise<void> {
  return new Promise((resolve) => setTimeout(resolve, ms));
}

function claudeConfigDir(): string {
  const configured = process.env.CLAUDE_CONFIG_DIR?.trim();
  return configured?.length ? configured : path.join(os.homedir(), ".claude");
}

function claudeBackgroundJobStatePath(short: string): string {
  return path.join(claudeConfigDir(), "jobs", short, "state.json");
}

function readClaudeBackgroundJobState(short: string | null | undefined): ClaudeBackgroundJobState | null {
  const normalizedShort = trimLine(short);
  if (!normalizedShort) return null;
  try {
    const parsed = JSON.parse(fs.readFileSync(claudeBackgroundJobStatePath(normalizedShort), "utf8")) as unknown;
    if (!parsed || typeof parsed !== "object") return null;
    return parsed as ClaudeBackgroundJobState;
  } catch {
    return null;
  }
}

function normalizeClaudeBackgroundShort(value: unknown): string | null {
  if (typeof value !== "string") return null;
  const trimmed = value.trim();
  return /^[A-Za-z0-9_-]{4,64}$/.test(trimmed) ? trimmed : null;
}

function parseClaudeBackgroundShort(text: string): string | null {
  const cleaned = stripAnsi(text);
  const backgrounded = cleaned.match(/backgrounded\s*[·•]\s*([A-Za-z0-9_-]{4,64})/i);
  if (backgrounded?.[1]) return backgrounded[1];
  const attach = cleaned.match(/\bclaude\s+attach\s+([A-Za-z0-9_-]{4,64})\b/i);
  return attach?.[1] ?? null;
}

function claudeBackgroundStateIsTerminal(state: ClaudeBackgroundJobState | null): boolean {
  const normalized = state?.state?.trim().toLowerCase();
  if (!normalized) return false;
  return normalized === "done"
    || normalized === "completed"
    || normalized === "failed"
    || normalized === "error"
    || normalized === "errored"
    || normalized === "stopped"
    || normalized === "killed"
    || normalized === "crashed";
}

function claudeBackgroundStateSucceeded(state: ClaudeBackgroundJobState | null): boolean {
  const normalized = state?.state?.trim().toLowerCase();
  return normalized === "done" || normalized === "completed";
}

function extractClaudeBackgroundStateText(state: ClaudeBackgroundJobState | null): string {
  const transcriptText = extractClaudeBackgroundTranscriptText(state);
  if (transcriptText) return transcriptText;
  const output = state?.output;
  if (typeof output === "string" && output.trim().length) return output.trim();
  if (output && typeof output === "object") {
    const record = output as Record<string, unknown>;
    for (const key of ["summary", "result", "message", "text"]) {
      const value = record[key];
      if (typeof value === "string" && value.trim().length) return value.trim();
    }
  }
  return typeof state?.detail === "string" ? state.detail.trim() : "";
}

function sanitizeClaudeBackgroundLog(value: string): string {
  return stripAnsi(value)
    .replace(/\u001b[78]/g, "")
    .replace(/\r\n/g, "\n")
    .replace(/\r/g, "\n")
    .replace(/\n{4,}/g, "\n\n\n")
    .trim();
}

function readFileTailUtf8(filePath: string, maxBytes = 512 * 1024): string {
  const stat = fs.statSync(filePath);
  const start = Math.max(0, stat.size - maxBytes);
  const length = stat.size - start;
  const fd = fs.openSync(filePath, "r");
  try {
    const buffer = Buffer.alloc(length);
    fs.readSync(fd, buffer, 0, length, start);
    const raw = buffer.toString("utf8");
    if (start === 0) return raw;
    const firstNewline = raw.indexOf("\n");
    return firstNewline >= 0 ? raw.slice(firstNewline + 1) : raw;
  } finally {
    fs.closeSync(fd);
  }
}

function claudeMessageContentText(content: unknown): string | null {
  if (typeof content === "string") return content.trim() || null;
  if (!Array.isArray(content)) return null;
  const parts = content
    .map((part) => {
      if (!part || typeof part !== "object") return "";
      const record = part as Record<string, unknown>;
      if (record.type !== "text") return "";
      return typeof record.text === "string" ? record.text : "";
    })
    .filter((part) => part.trim().length > 0);
  return parts.length ? parts.join("\n").trim() : null;
}

function extractClaudeBackgroundTranscriptText(state: ClaudeBackgroundJobState | null): string {
  const rawPath = trimLine(state?.linkScanPath);
  if (!rawPath) return "";
  const resolvedPath = path.resolve(rawPath);
  const configRoot = path.resolve(claudeConfigDir());
  if (!resolvedPath.startsWith(`${configRoot}${path.sep}`)) return "";
  if (!fs.existsSync(resolvedPath)) return "";
  let realPath = resolvedPath;
  let realConfigRoot = configRoot;
  try {
    realPath = fs.realpathSync(resolvedPath);
    realConfigRoot = fs.realpathSync(configRoot);
  } catch {
    return "";
  }
  if (!realPath.startsWith(`${realConfigRoot}${path.sep}`)) return "";
  try {
    const text = readFileTailUtf8(realPath);
    let latest = "";
    for (const line of text.split(/\n+/)) {
      if (!line.trim()) continue;
      let parsed: unknown;
      try {
        parsed = JSON.parse(line);
      } catch {
        continue;
      }
      if (!parsed || typeof parsed !== "object") continue;
      const record = parsed as Record<string, unknown>;
      if (record.type !== "assistant") continue;
      const message = record.message && typeof record.message === "object"
        ? record.message as Record<string, unknown>
        : null;
      if (message?.role !== "assistant") continue;
      const contentText = claudeMessageContentText(message.content);
      if (contentText) latest = contentText;
    }
    return latest.trim();
  } catch {
    return "";
  }
}

function claudeDaemonBaseDir(): string | null {
  try {
    const uid = typeof process.getuid === "function" ? process.getuid() : os.userInfo().uid;
    return path.join(os.tmpdir(), `cc-daemon-${uid}`);
  } catch {
    return null;
  }
}

async function sendClaudeDaemonRequest(
  socketPath: string,
  request: ClaudeDaemonRequest,
  timeoutMs = 2_500,
): Promise<ClaudeDaemonResponse> {
  return await new Promise<ClaudeDaemonResponse>((resolve, reject) => {
    const socket = net.createConnection(socketPath);
    let settled = false;
    let buffer = "";
    const finish = (fn: () => void) => {
      if (settled) return;
      settled = true;
      clearTimeout(timer);
      try { socket.destroy(); } catch { /* ignore */ }
      fn();
    };
    const timer = setTimeout(() => {
      finish(() => reject(new Error("Claude daemon request timed out.")));
    }, timeoutMs);
    socket.on("connect", () => {
      socket.write(`${JSON.stringify({ proto: 1, ...request })}\n`);
    });
    socket.on("data", (chunk) => {
      if (Buffer.byteLength(buffer, "utf8") + chunk.length > MAX_CLAUDE_DAEMON_RESPONSE_BYTES) {
        finish(() => reject(new Error("Claude daemon response exceeded the 1MB limit.")));
        return;
      }
      buffer += chunk.toString("utf8");
      const newline = buffer.indexOf("\n");
      const raw = (newline >= 0 ? buffer.slice(0, newline) : buffer).trim();
      if (!raw) return;
      try {
        const parsed = JSON.parse(raw) as ClaudeDaemonResponse;
        finish(() => resolve(parsed));
      } catch {
        // Wait for more bytes.
      }
    });
    socket.on("end", () => {
      const raw = buffer.trim();
      if (!raw) {
        finish(() => reject(new Error("Claude daemon closed without a response.")));
        return;
      }
      try {
        const parsed = JSON.parse(raw) as ClaudeDaemonResponse;
        finish(() => resolve(parsed));
      } catch (error) {
        finish(() => reject(error instanceof Error ? error : new Error(String(error))));
      }
    });
    socket.on("error", (error) => {
      finish(() => reject(error));
    });
  });
}

async function resolveClaudeDaemonControlSocket(): Promise<string | null> {
  const baseDir = claudeDaemonBaseDir();
  if (!baseDir || !fs.existsSync(baseDir)) return null;
  let entries;
  try {
    entries = fs.readdirSync(baseDir, { withFileTypes: true });
  } catch {
    return null;
  }
  for (const entry of entries) {
    if (!entry.isDirectory()) continue;
    const socketPath = path.join(baseDir, entry.name, "control.sock");
    if (!fs.existsSync(socketPath)) continue;
    try {
      const pong = await sendClaudeDaemonRequest(socketPath, { op: "ping" });
      if (pong.ok === true) return socketPath;
    } catch {
      // Try the next candidate.
    }
  }
  return null;
}

